	"\t\t\t\"command\"\t\"version\"\n"
	"\t\t\t\"description\"\t\"Prints the engine version in the console.\"\n"
	"\t\t}\n"
	"\t\t\"9\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Clear console\"\n"
	"\t\t\t\"command\"\t\"clear\"\n"
	"\t\t\t\"description\"\t\"Empties the console.\"\n"
	"\t\t}\n"
	"\t}\n"
	"\t\"Developer tests\"\n"
	"\t{\n"
	"\t\t\"1\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Freeze test: single-thread rendering\"\n"
	"\t\t\t\"command\"\t\"mat_queue_mode 0\"\n"
	"\t\t\t\"description\"\t\"Draw on the game's main thread instead of a separate render thread (may lower fps). Main freeze test.\"\n"
	"\t\t}\n"
	"\t\t\"2\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Multi-thread rendering (default)\"\n"
	"\t\t\t\"command\"\t\"mat_queue_mode -1\"\n"
	"\t\t\t\"description\"\t\"Normal: the engine decides, which on PS5 uses a separate render thread.\"\n"
	"\t\t}\n"
	"\t\t\"3\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Memory release fix on (default)\"\n"
	"\t\t\t\"command\"\t\"ps5_deferred_free 1\"\n"
	"\t\t\t\"description\"\t\"Free graphics memory only after the graphics chip has finished with it. Fix for the Barney/Kleiner freeze.\"\n"
	"\t\t}\n"
	"\t\t\"4\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Memory release fix off\"\n"
	"\t\t\t\"command\"\t\"ps5_deferred_free 0\"\n"
	"\t\t\t\"description\"\t\"Old behaviour: free graphics memory immediately (can freeze). For testing.\"\n"
	"\t\t}\n"
	"\t\t\"5\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Shader cache fix on (default)\"\n"
	"\t\t\t\"command\"\t\"ps5_shader_flush 1\"\n"
	"\t\t\t\"description\"\t\"Flush the graphics chip's caches the first times a newly built shader is used. Fix for the freeze when Kleiner/Barney appear.\"\n"
	"\t\t}\n"
	"\t\t\"6\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Shader cache fix: every draw\"\n"
	"\t\t\t\"command\"\t\"ps5_shader_flush 2\"\n"
	"\t\t\t\"description\"\t\"Flush shader caches on every draw (slower). Try this if the default still freezes.\"\n"
	"\t\t}\n"
	"\t\t\"7\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Shader cache fix off\"\n"
	"\t\t\t\"command\"\t\"ps5_shader_flush 0\"\n"
	"\t\t\t\"description\"\t\"Original behaviour (freezes sometimes, once per launch). For testing.\"\n"
	"\t\t}\n"
	"\t\t\"8\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Batch cache fix on\"\n"
	"\t\t\t\"command\"\t\"ps5_batch_flush 1\"\n"
	"\t\t\t\"description\"\t\"Every grouped draw flushes its own data caches instead of sharing one (a bit slower). Extra freeze test.\"\n"
	"\t\t}\n"
	"\t\t\"9\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Batch cache fix off (default)\"\n"
	"\t\t\t\"command\"\t\"ps5_batch_flush 0\"\n"
	"\t\t\t\"description\"\t\"Original grouped-draw behaviour.\"\n"
	"\t\t}\n"
	"\t\t\"10\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Monitor lock-step on\"\n"
	"\t\t\t\"command\"\t\"ps5_monitor_sync 1\"\n"
	"\t\t\t\"description\"\t\"When a security camera first starts, wait for the graphics chip on each draw for a moment. Did not stop the freeze; for testing.\"\n"
	"\t\t}\n"
	"\t\t\"11\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Freeze test: CPU frame copy on\"\n"
	"\t\t\t\"command\"\t\"ps5_cpu_present 1\"\n"
	"\t\t\t\"description\"\t\"Copy each finished frame to the screen with the CPU instead of the graphics chip (lower fps). Freeze test.\"\n"
	"\t\t}\n"
	"\t\t\"12\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Freeze test: CPU frame copy off (default)\"\n"
	"\t\t\t\"command\"\t\"ps5_cpu_present 0\"\n"
	"\t\t\t\"description\"\t\"Normal: the graphics chip copies each frame to the screen.\"\n"
	"\t\t}\n"
	"\t\t\"13\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Freeze test: CPU frame flip on\"\n"
	"\t\t\t\"command\"\t\"ps5_cpu_flip 1\"\n"
	"\t\t\t\"description\"\t\"Wait for the graphics chip to finish each frame, then show it (slightly lower fps). Freeze test.\"\n"
	"\t\t}\n"
	"\t\t\"14\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Freeze test: CPU frame flip off (default)\"\n"
	"\t\t\t\"command\"\t\"ps5_cpu_flip 0\"\n"
	"\t\t\t\"description\"\t\"Normal: the frame is shown as soon as the graphics chip reaches it.\"\n"
	"\t\t}\n"
	"\t\t\"15\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Freeze test: all CPU screen copies on\"\n"
	"\t\t\t\"command\"\t\"ps5_cpu_blits 1\"\n"
	"\t\t\t\"description\"\t\"Every screen copy (frame, water/glass refraction, effects) done by the CPU (much lower fps). Freeze test.\"\n"
	"\t\t}\n"
	"\t\t\"16\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Freeze test: all CPU screen copies off (default)\"\n"
	"\t\t\t\"command\"\t\"ps5_cpu_blits 0\"\n"
	"\t\t\t\"description\"\t\"Normal: the graphics chip does screen copies.\"\n"
	"\t\t}\n"
	"\t\t\"17\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Monitor lock-step long\"\n"
	"\t\t\t\"command\"\t\"ps5_monitor_sync 2\"\n"
	"\t\t\t\"description\"\t\"When a security camera first starts, wait for the graphics chip after every draw for about a minute (slow while it lasts). Freeze test.\"\n"
	"\t\t}\n"
	"\t\t\"18\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Monitor lock-step off (default)\"\n"
	"\t\t\t\"command\"\t\"ps5_monitor_sync 0\"\n"
	"\t\t\t\"description\"\t\"No waiting when a monitor camera starts.\"\n"
	"\t\t}\n"
	"\t\t\"19\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Freeze fix test: hide monitor overlay\"\n"
	"\t\t\t\"command\"\t\"ps5_skip_material dev/dev_prisontvoverlay\"\n"
	"\t\t\t\"description\"\t\"Hide the TV overlay drawn on top of security monitors (the last thing drawn before every freeze). The live picture stays.\"\n"
	"\t\t}\n"
	"\t\t\"20\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Freeze fix test: draw monitor overlay\"\n"
	"\t\t\t\"command\"\t\"ps5_skip_material\"\n"
	"\t\t\t\"description\"\t\"Draw the monitor overlay again.\"\n"
	"\t\t}\n"
	"\t\t\"21\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Freeze finder: lock-step drawing ON\"\n"
	"\t\t\t\"command\"\t\"ps5_sync_draws 1\"\n"
	"\t\t\t\"description\"\t\"Slow: waits for the graphics chip after every draw, so a freeze stops on the exact draw that causes it. Turn on just before Barney's room, wait 10 s after a freeze, then send the next launch's log.\"\n"
	"\t\t}\n"
	"\t\t\"22\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Freeze finder: lock-step drawing off\"\n"
	"\t\t\t\"command\"\t\"ps5_sync_draws 0\"\n"
	"\t\t\t\"description\"\t\"Normal speed again.\"\n"
	"\t\t}\n"
	"\t\t\"23\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Monitor test A: no eyes\"\n"
	"\t\t\t\"command\"\t\"cl_drawmonitors 1; r_eyes 0\"\n"
	"\t\t\t\"description\"\t\"Screens on, characters' eyes not drawn. Run near Barney's screen: does it still freeze?\"\n"
	"\t\t}\n"
	"\t\t\"24\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Monitor test B: no face animation\"\n"
	"\t\t\t\"command\"\t\"cl_drawmonitors 1; r_eyes 1; r_flex 0\"\n"
	"\t\t\t\"description\"\t\"Screens on, eyes back, facial animation off. Does it still freeze?\"\n"
	"\t\t}\n"
	"\t\t\"25\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Monitor test C: no 3D skybox\"\n"
	"\t\t\t\"command\"\t\"cl_drawmonitors 1; r_eyes 1; r_flex 1; r_3dsky 0\"\n"
	"\t\t\t\"description\"\t\"Screens on, distant 3D skybox off. Does it still freeze?\"\n"
	"\t\t}\n"
	"\t\t\"26\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Monitor test D: no characters\"\n"
	"\t\t\t\"command\"\t\"sv_cheats 1; cl_drawmonitors 1; r_eyes 1; r_flex 1; r_3dsky 1; r_drawothermodels 0\"\n"
	"\t\t\t\"description\"\t\"Screens on, no models drawn anywhere (cheat). Does it still freeze?\"\n"
	"\t\t}\n"
	"\t\t\"27\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Freeze test: skip monitor shader\"\n"
	"\t\t\t\"command\"\t\"ps5_skip_shader unlittwotexture\"\n"
	"\t\t\t\"description\"\t\"Don't draw surfaces using the UnlitTwoTexture shader (the security monitors). If the freeze stops, that confirms the cause.\"\n"
	"\t\t}\n"
	"\t\t\"28\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Clear camera picture now\"\n"
	"\t\t\t\"command\"\t\"ps5_camera_rt_clear\"\n"
	"\t\t\t\"description\"\t\"Give the monitors' camera picture defined contents (test; off by default).\"\n"
	"\t\t}\n"
	"\t\t\"29\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Freeze test: draw everything\"\n"
	"\t\t\t\"command\"\t\"ps5_skip_shader\"\n"
	"\t\t\t\"description\"\t\"Undo the skip test (draw all shaders again).\"\n"
	"\t\t}\n"
	"\t\t\"30\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Teleport guard on\"\n"
	"\t\t\t\"command\"\t\"ps5_model_guard 1\"\n"
	"\t\t\t\"description\"\t\"Don't draw a character on the frame it is teleported, or with broken bone data. Prevents the Kleiner/Barney teleport freeze.\"\n"
	"\t\t}\n"
	"\t\t\"31\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Teleport guard off (default)\"\n"
	"\t\t\t\"command\"\t\"ps5_model_guard 0\"\n"
	"\t\t\t\"description\"\t\"Draw every model every frame (the original behaviour).\"\n"
	"\t\t}\n"
	"\t\t\"32\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Character test E: software skinning\"\n"
	"\t\t\t\"command\"\t\"sv_cheats 1; mat_softwareskin 1\"\n"
	"\t\t\t\"description\"\t\"Bend character models on the CPU instead of the GPU. Does the freeze stop?\"\n"
	"\t\t}\n"
	"\t\t\"33\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Character test F: no shadows\"\n"
	"\t\t\t\"command\"\t\"mat_softwareskin 0; r_shadows 0\"\n"
	"\t\t\t\"description\"\t\"Characters and objects without their soft shadows. Does the freeze stop?\"\n"
	"\t\t}\n"
	"\t\t\"34\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Character test G: no teeth/mouths\"\n"
	"\t\t\t\"command\"\t\"r_shadows 1; r_teeth 0\"\n"
	"\t\t\t\"description\"\t\"Characters drawn without teeth. Does the freeze stop?\"\n"
	"\t\t}\n"
	"\t\t\"35\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Character test H: no see-through parts\"\n"
	"\t\t\t\"command\"\t\"sv_cheats 1; r_teeth 1; r_drawtranslucentrenderables 0\"\n"
	"\t\t\t\"description\"\t\"Skip glass, glasses and other see-through parts. Does the freeze stop?\"\n"
	"\t\t}\n"
	"\t\t\"36\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Character tests: reset\"\n"
	"\t\t\t\"command\"\t\"mat_softwareskin 0; r_shadows 1; r_teeth 1; r_drawtranslucentrenderables 1\"\n"
	"\t\t\t\"description\"\t\"Undo the character tests.\"\n"
	"\t\t}\n"
	"\t\t\"37\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Monitor tests: reset\"\n"
	"\t\t\t\"command\"\t\"r_eyes 1; r_flex 1; r_3dsky 1; r_drawothermodels 1\"\n"
	"\t\t\t\"description\"\t\"Undo the monitor tests.\"\n"
	"\t\t}\n"
	"\t\t\"38\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Sound freeze test: play new sounds\"\n"
	"\t\t\t\"command\"\t\"ps5_freeze_recorder 1; ps5_sound_stress play 300\"\n"
	"\t\t\t\"description\"\t\"Plays up to 300 voice/NPC/ambient sounds the game hasn't used yet, one every few frames, to reproduce the freeze from the menu. Recorder on.\"\n"
	"\t\t}\n"
	"\t\t\"39\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Sound freeze test: load new sounds only\"\n"
	"\t\t\t\"command\"\t\"ps5_freeze_recorder 1; ps5_sound_stress load 300\"\n"
	"\t\t\t\"description\"\t\"Same, but only loads each sound without playing it (tells loading apart from playing).\"\n"
	"\t\t}\n"
	"\t\t\"40\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Sound freeze test: stop\"\n"
	"\t\t\t\"command\"\t\"ps5_sound_stress_stop\"\n"
	"\t\t\t\"description\"\t\"Stop the sound freeze test.\"\n"
	"\t\t}\n"
	"\t\t\"41\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Freeze recorder on\"\n"
	"\t\t\t\"command\"\t\"ps5_freeze_recorder 1\"\n"
	"\t\t\t\"description\"\t\"Record every draw to crumbs.bin so the next launch can report a freeze (costs some fps). Also: -ps5_freeze_recorder in args.txt.\"\n"
	"\t\t}\n"
	"\t\t\"42\"\n"
	"\t\t{\n"
	"\t\t\t\"label\"\t\"Freeze recorder off (default)\"\n"
	"\t\t\t\"command\"\t\"ps5_freeze_recorder 0\"\n"
	"\t\t\t\"description\"\t\"Stop recording draws.\"\n"
	"\t\t}\n"
	"\t}\n"
	"}\n";
